from decimal import Decimal
from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import status
from django.shortcuts import get_object_or_404
from django.db import models
from .models import (
    VendorInvoice, PaymentDisbursement, GoodsReceiptLine, VendorCreditMemo
)


class InvoiceMatchView(APIView):
    def post(self, request, id=None):
        invoice = get_object_or_404(VendorInvoice, id=id)

        discrepancies = []
        for line in invoice.lines.all():
            # Check quantity against cumulative GoodsReceiptLines for this PO line
            total_received = GoodsReceiptLine.objects.filter(
                po_line=line.po_line
            ).aggregate(total=models.Sum('quantity_received'))['total'] or 0

            if line.quantity > total_received:
                discrepancies.append(
                    f"Line {line.id}: Invoiced qty ({line.quantity}) exceeds received qty ({total_received})"
                )

            # Check unit price tolerance (max 2% above PO line price)
            po_price = line.po_line.unit_price
            max_allowed_price = po_price * Decimal('1.02')
            if line.unit_price > max_allowed_price:
                discrepancies.append(
                    f"Line {line.id}: Invoiced price ({line.unit_price}) exceeds PO price ({po_price}) by >2%"
                )

        if discrepancies:
            invoice.status = 'ON_HOLD'
            invoice.discrepancy_reason = "; ".join(discrepancies)
            invoice.save()
            return Response({
                "status": "ON_HOLD",
                "invoice_number": invoice.invoice_number,
                "discrepancy_reason": invoice.discrepancy_reason
            }, status=status.HTTP_200_OK)

        invoice.status = 'MATCHED'
        invoice.discrepancy_reason = None
        invoice.save()

        return Response({
            "status": "MATCHED",
            "invoice_number": invoice.invoice_number
        }, status=status.HTTP_200_OK)


class InvoiceApproveView(APIView):
    def post(self, request, id=None):
        invoice = get_object_or_404(VendorInvoice, id=id)
        role = request.data.get("role")

        # Determine required approval hierarchy based on total amount
        if invoice.total_amount <= Decimal("5000.00"):
            required_roles = ["MANAGER"]
        elif invoice.total_amount <= Decimal("50000.00"):
            required_roles = ["MANAGER", "DIRECTOR"]
        else:
            required_roles = ["MANAGER", "DIRECTOR", "CFO"]

        current_approvals = list(invoice.approvals or [])

        # Check if already fully approved
        if len(current_approvals) >= len(required_roles):
            return Response({
                "status": invoice.status,
                "approvals": current_approvals
            }, status=status.HTTP_200_OK)

        # The next expected role in sequence
        expected_role = required_roles[len(current_approvals)]
        if role != expected_role:
            return Response({
                "error": f"Invalid approval sequence. Expected role: {expected_role}, received: {role}"
            }, status=status.HTTP_403_FORBIDDEN)

        # Record valid approval
        current_approvals.append(role)
        invoice.approvals = current_approvals

        if len(current_approvals) == len(required_roles):
            invoice.status = "APPROVED"

        invoice.save()

        return Response({
            "status": invoice.status,
            "invoice_number": invoice.invoice_number,
            "approvals": invoice.approvals
        }, status=status.HTTP_200_OK)


class InvoicePayView(APIView):
    def post(self, request, id=None):
        invoice = get_object_or_404(VendorInvoice, id=id)

        # Retrieve open vendor credit memos in FIFO order
        open_memos = VendorCreditMemo.objects.filter(
            vendor=invoice.vendor, status='OPEN'
        ).order_by('created_at')

        remaining_invoice_amount = invoice.total_amount
        total_credit_applied = Decimal('0.00')

        for memo in open_memos:
            if remaining_invoice_amount <= Decimal('0.00'):
                break
            if memo.amount <= remaining_invoice_amount:
                total_credit_applied += memo.amount
                remaining_invoice_amount -= memo.amount
                memo.status = 'CONSUMED'
                memo.save()
            else:
                total_credit_applied += remaining_invoice_amount
                memo.amount -= remaining_invoice_amount
                remaining_invoice_amount = Decimal('0.00')
                memo.save()

        net_cash_paid = invoice.total_amount - total_credit_applied

        disbursement = PaymentDisbursement.objects.create(
            invoice=invoice,
            amount_paid=net_cash_paid,
            credit_applied=total_credit_applied
        )

        invoice.paid_amount = invoice.total_amount
        invoice.status = 'PAID'
        invoice.save()

        return Response({
            "status": "PAID",
            "invoice_number": invoice.invoice_number,
            "amount_paid": str(disbursement.amount_paid),
            "credit_applied": str(disbursement.credit_applied)
        }, status=status.HTTP_200_OK)
